BEGIN
  -- ── Décor ───────────────────────────────────────────────────────────
  PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
  INSERT INTO public.network_administrators (user_id, status) VALUES (v_admin, 'active');
  INSERT INTO public.catalog_ref_source_partners (code, label, sort_order, is_active)
  VALUES ('other_partner', 'Outro parceiro', 80, true) ON CONFLICT (code) DO NOTHING;
  UPDATE public.libraries SET tombo_pattern = '{"prefix": "L7-T-", "year": false, "pad": 4}'::jsonb WHERE id = v_lib;
  INSERT INTO public.libraries (id, slug, name, is_active, visibility_level, tombo_pattern)
  VALUES (gen_random_uuid(), 'essai-h21-l7-b', 'Essai H21 lot 7 — B', true, 'private',
          '{"prefix": "L7B-T-", "year": false, "pad": 4}'::jsonb)
  RETURNING id INTO v_libB;
  UPDATE public.user_library_memberships SET status = 'inactive', is_primary = false WHERE user_id = v_coordB;
  INSERT INTO public.user_library_memberships (user_id, library_id, role, status, is_primary)
  VALUES (v_coordB, v_libB, 'coordenador', 'active', true);
  ALTER TABLE public.interlibrary_loans_v2 DISABLE TRIGGER trg_interlibrary_loan_enqueue_notifications;

  INSERT INTO ingest.partner_catalog_sources (partner_name, library_id, relation_status, source_kind, import_enabled)
  VALUES ('L7 PMB 8.1 (fixtures)', v_lib, 'mapeada', 'own_catalog', true) RETURNING id INTO v_src;
  INSERT INTO ingest.partner_catalog_sources (partner_name, library_id, relation_status, source_kind, import_enabled)
  VALUES ('L7 autre source', v_lib, 'mapeada', 'own_catalog', true) RETURNING id INTO v_src2;

  -- Premier import : promu, révisé, publié.
  INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
  VALUES (v_src, v_lib, 'essai/l7-pmb.iso', 'l7-pmb.iso', 'marc_iso2709', 'ready_for_review') RETURNING id INTO v_run1;
  INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, item_type, title, subtitle, responsibility_statement, authors, publisher, place_of_publication, publication_year, edition_statement, language, isbn, issn, subjects, raw_payload, normalized_payload, match_status, editorial_decision)
  SELECT v_run1, r.row_no, r.external_key, r.item_type, r.title, r.subtitle, r.responsibility_statement, r.authors, r.publisher, r.place_of_publication, r.publication_year, r.edition_statement, r.language, r.isbn, r.issn, r.subjects, r.raw_payload, r.normalized_payload, 'new_record', 'accept_new'
    FROM jsonb_to_recordset(v_pmb)
      AS r(row_no integer, external_key text, item_type text, title text, subtitle text, responsibility_statement text, authors jsonb, publisher text, place_of_publication text, publication_year text, edition_statement text, language text, isbn text, issn text, subjects jsonb, raw_payload jsonb, normalized_payload jsonb);
  v_res := public.fn_import_promote(v_run1, ARRAY['new_record'], ARRAY['accept_new']);
  v_lot1 := (v_res->>'batch_id')::bigint;
  UPDATE public.book_drafts SET bib_ref = 'L7-PMB-REF-' || id WHERE batch_id = v_lot1 AND bib_ref IS NULL;
  v_res := public.fn_batch_review_request(v_lot1);
  PERFORM set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
  PERFORM public.fn_batch_review_verdict((v_res->>'review_id')::bigint, 'approved', NULL);
  PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
  PERFORM public.publish_catalog_batch(v_lot1);
  IF (SELECT count(*) FROM public.book_drafts WHERE batch_id = v_lot1 AND status = 'published') <> 64 THEN
    RAISE EXCEPTION 'decor : publication incomplete';
  END IF;
  SELECT max(e.id) FILTER (WHERE e.source_item_code = '33700003413727'), max(e.id) FILTER (WHERE e.source_item_code = '33700003669468'),
         max(e.id) FILTER (WHERE e.source_item_code = '33700003669484'), max(e.id) FILTER (WHERE e.source_item_code = '33700003669485'),
         max(e.id) FILTER (WHERE e.source_item_code = '33700004243164'), max(e.id) FILTER (WHERE e.source_item_code = '33700003868672'),
         max(e.id) FILTER (WHERE e.source_item_code = '33700004243347'), max(e.id) FILTER (WHERE e.source_item_code = '33700003453202'),
         max(e.id) FILTER (WHERE e.source_item_code = '33700003286792'), max(e.id) FILTER (WHERE e.source_item_code = '3370000451291'),
         max(e.id) FILTER (WHERE e.source_item_code = '3370000451290'), max(e.id) FILTER (WHERE e.source_item_code = '3370000451292'),
         max(e.id) FILTER (WHERE e.source_item_code = '3370000451295'), max(e.id) FILTER (WHERE e.source_item_code = '3370000451294')
    INTO e3, e8, e9, e10, e11, e12, e13, e14, e16, e17, e18, e19, e37, e36
    FROM public.exemplares e WHERE e.library_id = v_lib;
  SELECT max(h.book_id) FILTER (WHERE e.id = e3), max(h.id) FILTER (WHERE e.id = e3)
    INTO b3, h3 FROM public.exemplares e JOIN public.book_holdings h ON h.id = e.holding_id WHERE e.id = e3;
  SELECT h.book_id INTO b35 FROM public.exemplares e JOIN public.book_holdings h ON h.id = e.holding_id
   WHERE e.library_id = v_lib AND e.source_item_code = '3370000451293';
  SELECT h.book_id INTO b36 FROM public.exemplares e JOIN public.book_holdings h ON h.id = e.holding_id
   WHERE e.library_id = v_lib AND e.source_item_code = '3370000451294';
  IF e3 IS NULL OR e8 IS NULL OR e13 IS NULL OR e19 IS NULL OR e37 IS NULL OR b35 IS NULL OR b36 IS NULL
     OR (SELECT count(*) FROM public.exemplares WHERE holding_id = h3) <> 1
     OR EXISTS (SELECT 1 FROM public.exemplares WHERE id IN (e3, e8, e9, e10, e11, e12, e13, e14, e16, e17, e18, e19, e37)
                 AND import_source_id IS DISTINCT FROM v_src) THEN
    RAISE EXCEPTION 'decor : fixture inattendue';
  END IF;
  -- l'exemplaire du rang 3 est consultable (pour la consultation, T14) et
  -- porte une étiquette (la copie la reprend)
  UPDATE public.exemplares SET circulation_policy = 'ambos', label_note = 'L7 etiquette' WHERE id = e3;
  UPDATE public.exemplares SET circulation_policy = 'ambos' WHERE id = e16;

  -- Le réimport : déposé (uploaded), « export complet » déclaré, puis analysé.
  INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
  VALUES (v_src, v_lib, 'essai/l7-pmb-reimport.iso', 'l7-pmb-reimport.iso', 'marc_iso2709', 'uploaded') RETURNING id INTO v_run2;
  EXECUTE 'SET LOCAL ROLE authenticated';
  BEGIN v_res := public.fn_import_set_export_complet(v_run2, true); v_hint := 'ok';
  EXCEPTION WHEN OTHERS THEN v_hint := SQLERRM; END;
  EXECUTE 'RESET ROLE';
  UPDATE ingest.partner_catalog_import_runs SET run_status = 'ready_for_review' WHERE id = v_run2;
  INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, item_type, title, subtitle, responsibility_statement, authors, publisher, place_of_publication, publication_year, edition_statement, language, isbn, issn, subjects, raw_payload, normalized_payload, match_status, editorial_decision)
  SELECT v_run2, r.row_no, r.external_key, r.item_type, r.title, r.subtitle, r.responsibility_statement, r.authors, r.publisher, r.place_of_publication, r.publication_year, r.edition_statement, r.language, r.isbn, r.issn, r.subjects, r.raw_payload, r.normalized_payload, 'unreviewed', 'pending'
    FROM jsonb_to_recordset(v_pmb)
      AS r(row_no integer, external_key text, item_type text, title text, subtitle text, responsibility_statement text, authors jsonb, publisher text, place_of_publication text, publication_year text, edition_statement text, language text, isbn text, issn text, subjects jsonb, raw_payload jsonb, normalized_payload jsonb);
  -- dans le fichier : les absents
  UPDATE ingest.partner_catalog_staging_rows SET normalized_payload = jsonb_set(normalized_payload, '{items}', '[]'::jsonb)
   WHERE run_id = v_run2 AND row_no IN (3, 8, 9, 10, 11, 12, 13, 17, 19);
  -- le rang 14 déplacé dans PMB sous la notice du rang 15
  UPDATE ingest.partner_catalog_staging_rows
     SET normalized_payload = jsonb_set(normalized_payload, '{items}', (normalized_payload->'items')
           || (SELECT s.normalized_payload->'items' FROM ingest.partner_catalog_staging_rows s WHERE s.run_id = v_run2 AND s.row_no = 14))
   WHERE run_id = v_run2 AND row_no = 15;
  UPDATE ingest.partner_catalog_staging_rows SET normalized_payload = jsonb_set(normalized_payload, '{items}', '[]'::jsonb)
   WHERE run_id = v_run2 AND row_no = 14;
  -- le rang 16 réétiqueté (expl_id égal)
  UPDATE ingest.partner_catalog_staging_rows SET normalized_payload = jsonb_set(normalized_payload, '{items,0,source_item_code}', '"L7-REETIQUETE-16"')
   WHERE run_id = v_run2 AND row_no = 16;
  -- le rang 36 : l'exemplaire du fichier sans son identifiant interne (le code seul le désigne)
  UPDATE ingest.partner_catalog_staging_rows SET normalized_payload = normalized_payload #- '{items,0,source_item_id}'
   WHERE run_id = v_run2 AND row_no = 36;
  -- la ligne du rang 18 absente du fichier
  DELETE FROM ingest.partner_catalog_staging_rows WHERE run_id = v_run2 AND row_no = 18;
  SELECT max(id) FILTER (WHERE row_no = 3), max(id) FILTER (WHERE row_no = 8), max(id) FILTER (WHERE row_no = 19)
    INTO r3, r8, r19 FROM ingest.partner_catalog_staging_rows WHERE run_id = v_run2;
  -- dans AnarBib : l'exemplaire du rang 17 venu d'une autre source
  UPDATE public.exemplares SET import_source_id = v_src2 WHERE id = e17;
  -- B : un exemplaire de la même source, absent du fichier
  INSERT INTO public.book_holdings (book_id, library_id, loanable) VALUES (b35, v_libB, true);
  INSERT INTO public.exemplares (bib_ref, tombo, library_id, holding_id, source_item_code, import_source_id, circulation_policy)
  SELECT b.bib_ref, 'L7B-X-1', v_libB, h.id, 'L7-B-1', v_src, 'ambos'
    FROM public.books b JOIN public.book_holdings h ON h.book_id = b.id AND h.library_id = v_libB WHERE b.id = b35
  RETURNING id INTO eB;
  -- BLMF : un exemplaire fait à la main sur la notice du rang 36
  INSERT INTO public.exemplares (bib_ref, tombo, library_id, holding_id, source_item_code, circulation_policy)
  SELECT b.bib_ref, 'L7-MAIN-1', v_lib, h.id, 'L7-MAIN-1', 'ambos'
    FROM public.books b JOIN public.book_holdings h ON h.book_id = b.id AND h.library_id = v_lib WHERE b.id = b36
  RETURNING id INTO eMain;
  -- engagés : prêt (9), réservation au niveau du fonds (10), PEB (11), consultation (12)
  INSERT INTO public.emprestimos_v2 (user_id, library_id, status_global, due_at)
  VALUES (v_lect, v_lib, 'aberto', current_date + 30) RETURNING id INTO v_emp;
  INSERT INTO public.emprestimo_itens_v2 (emprestimo_id, line_no, sub_id, book_id, item_id, holding_id, bib_ref, due_at)
  SELECT v_emp, 1, v_emp || '.1', h.book_id, e.id, e.holding_id, e.bib_ref, current_date + 30
    FROM public.exemplares e JOIN public.book_holdings h ON h.id = e.holding_id WHERE e.id = e9;
  INSERT INTO public.reservas_v2 (user_id, library_id, status_global) VALUES (v_admin, v_lib, 'ativa') RETURNING id INTO v_resv;
  INSERT INTO public.reserva_linhas_v2 (reserva_id, line_no, book_id, item_id, holding_id, bib_ref)
  SELECT v_resv, 1, h.book_id, NULL, e.holding_id, e.bib_ref
    FROM public.exemplares e JOIN public.book_holdings h ON h.id = e.holding_id WHERE e.id = e10;
  INSERT INTO public.interlibrary_loans_v2 (lender_library_id, borrower_library_id, initiated_by_library_id, status_global)
  VALUES (v_lib, v_libB, v_lib, 'preparacao') RETURNING id INTO v_ill;
  INSERT INTO public.interlibrary_loan_items_v2 (interlibrary_loan_id, line_no, book_id, holding_id, item_id, bib_ref, item_status)
  SELECT v_ill, 1, h.book_id, e.holding_id, e.id, e.bib_ref, 'reservado_para_saida'
    FROM public.exemplares e JOIN public.book_holdings h ON h.id = e.holding_id WHERE e.id = e11;
  INSERT INTO public.consultas_locais_v2 (user_id, library_id) VALUES (v_lect, v_lib) RETURNING id INTO v_cons;
  INSERT INTO public.consulta_linhas_v2 (consulta_id, line_no, book_id, holding_id, item_id, bib_ref)
  SELECT v_cons, 1, h.book_id, e.holding_id, e.id, e.bib_ref
    FROM public.exemplares e JOIN public.book_holdings h ON h.id = e.holding_id WHERE e.id = e12;
  PERFORM public.fn_v2_recompute_holdings_availability(p_holding_ids := NULL);
  -- un « Éditer » en cours sur l'exemplaire du rang 13
  dEdit13 := public.create_exemplar_draft_from_exemplar(e13, NULL);
  PERFORM ingest.fn_match_partner_catalog_run(v_run2);
  IF (SELECT count(*) FROM ingest.partner_catalog_staging_rows WHERE run_id = v_run2 AND match_status = 'known_record') <> 63 THEN
    RAISE EXCEPTION 'decor : reimport non reconnu';
  END IF;
  EXECUTE 'SET LOCAL ROLE authenticated';
  PERFORM public.fn_import_set_editorial(v_run2, ARRAY[r19], 'reject', 'page import: écarté');
  EXECUTE 'RESET ROLE';
  -- l'OPAC et l'export avant tout retrait
  REFRESH MATERIALIZED VIEW public.mv_books_catalog_list_v1;
  EXECUTE 'SET LOCAL ROLE anon';
  PERFORM set_config('request.jwt.claims', json_build_object('role', 'anon')::text, true);
  SELECT count(*) INTO v_opac_avant FROM api.catalog_list_anon_v1 WHERE book_id = b3;
  EXECUTE 'RESET ROLE';
  PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
  v_res := public.fn_export_catalog_lote(v_lib, b3 - 1, 1);
  v_export_avant := coalesce(jsonb_array_length(v_res->'records'->0->'items'), 0);
  IF (v_res->'records'->0->>'id')::bigint IS DISTINCT FROM b3 OR v_opac_avant <> 1 THEN
    RAISE EXCEPTION 'decor : OPAC % / export %', v_opac_avant, v_res->'records'->0->>'id';
  END IF;

  -- Empreintes : tout le catalogue, hors le marqueur, hors les comptes du
  -- fonds et de la notice, hors updated_at.
  v_ref := 'select md5(concat_ws(''|'',
      (select string_agg(md5((to_jsonb(b) - array[''available_count'', ''updated_at''])::text), '','' order by b.id) from public.books b),
      (select string_agg(md5((to_jsonb(h) - array[''exemplares_total'', ''available_count'', ''updated_at''])::text), '','' order by h.id) from public.book_holdings h),
      (select string_agg(md5((to_jsonb(e) - array[''retire_at'', ''retire_run_id'', ''retire_trace'', ''updated_at''])::text), '','' order by e.id) from public.exemplares e),
      (select string_agg(md5(to_jsonb(x)::text), '','' order by x.id) from public.book_external_ids x),
      (select string_agg(md5(to_jsonb(i)::text), '','' order by i.id) from public.emprestimo_itens_v2 i),
      (select string_agg(md5(to_jsonb(l)::text), '','' order by l.id) from public.reserva_linhas_v2 l),
      (select string_agg(md5(to_jsonb(c)::text), '','' order by c.id) from public.consulta_linhas_v2 c),
      (select string_agg(md5(to_jsonb(p)::text), '','' order by p.id) from public.interlibrary_loan_items_v2 p),
      (select string_agg(md5(to_jsonb(s)::text), '','' order by s.id) from public.recolement_scans s)))';
  v_hold_avant := (SELECT string_agg(h.id || ':' || h.exemplares_total || '/' || h.available_count, ',' ORDER BY h.id)
                     FROM public.book_holdings h WHERE h.id <> h3);

  -- ── T1 ──────────────────────────────────────────────────────────────
  v_t := 'T1 le drapeau export complet pose avant le dispatch, par la coordination (qui, quand)';
  BEGIN
    IF v_hint = 'ok'
       AND (SELECT export_complet AND export_complet_par = v_coord AND export_complet_le IS NOT NULL
              FROM ingest.partner_catalog_import_runs WHERE id = v_run2)
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||coalesce(v_hint, '∅')); END IF;
  EXCEPTION WHEN OTHERS THEN v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T2 ──────────────────────────────────────────────────────────────
  v_t := 'T2 drapeau refuse apres le dispatch (statut, demarre, journal), aux non-coordinations, au depot compagnon';
  DECLARE v_h text[] := ARRAY[]::text[]; v_x text; v_runU bigint; v_runD bigint;
  BEGIN
    INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
    VALUES (v_src, v_lib, 'essai/l7-u.iso', 'l7-u.iso', 'marc_iso2709', 'uploaded') RETURNING id INTO v_runU;
    INSERT INTO ingest.partner_catalog_sources (partner_name, library_id, relation_status, source_kind, import_enabled, destination_library_id)
    VALUES ('L7 depot', v_lib, 'mutualizacao_autorizada', 'partner_deposit', true, v_lib) RETURNING id INTO v_srcD;
    INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
    VALUES (v_srcD, v_lib, 'essai/l7-d.iso', 'l7-d.iso', 'marc_iso2709', 'uploaded') RETURNING id INTO v_runD;
    EXECUTE 'SET LOCAL ROLE authenticated';
    -- (a) analysé
    BEGIN PERFORM public.fn_import_set_export_complet(v_run2, false); v_x := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_x = PG_EXCEPTION_HINT; END;
    v_h := v_h || v_x;
    EXECUTE 'RESET ROLE';
    -- (b) déjà démarré
    UPDATE ingest.partner_catalog_import_runs SET started_at = now() WHERE id = v_runU;
    EXECUTE 'SET LOCAL ROLE authenticated';
    BEGIN PERFORM public.fn_import_set_export_complet(v_runU, true); v_x := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_x = PG_EXCEPTION_HINT; END;
    v_h := v_h || v_x;
    EXECUTE 'RESET ROLE';
    -- (c) envoyé (journal du dispatch)
    UPDATE ingest.partner_catalog_import_runs SET started_at = NULL WHERE id = v_runU;
    INSERT INTO ingest.partner_catalog_import_dispatch_log (run_id, force_reparse, request_body, requested_by, dispatch_status)
    VALUES (v_runU, false, '{}'::jsonb, v_coord, 'sent');
    EXECUTE 'SET LOCAL ROLE authenticated';
    BEGIN PERFORM public.fn_import_set_export_complet(v_runU, true); v_x := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_x = PG_EXCEPTION_HINT; END;
    v_h := v_h || v_x;
    -- (d) dépôt compagnon : l'administration seule
    BEGIN PERFORM public.fn_import_set_export_complet(v_runD, true); v_x := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_x = PG_EXCEPTION_HINT; END;
    v_h := v_h || v_x;
    EXECUTE 'RESET ROLE';
    -- (e) lectrice, (f) librarian, (g) autre bibliothèque
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_lect, 'role', 'authenticated')::text, true);
    EXECUTE 'SET LOCAL ROLE authenticated';
    BEGIN PERFORM public.fn_import_set_export_complet(v_runD, true); v_x := 'accepte';
    EXCEPTION WHEN OTHERS THEN v_x := left(SQLERRM, 20); END;
    v_h := v_h || v_x;
    EXECUTE 'RESET ROLE';
    UPDATE public.user_library_memberships SET role = 'librarian' WHERE user_id = v_lect AND library_id = v_lib;
    EXECUTE 'SET LOCAL ROLE authenticated';
    BEGIN PERFORM public.fn_import_set_export_complet(v_runD, true); v_x := 'accepte';
    EXCEPTION WHEN OTHERS THEN v_x := left(SQLERRM, 20); END;
    v_h := v_h || v_x;
    EXECUTE 'RESET ROLE';
    UPDATE public.user_library_memberships SET role = 'reader' WHERE user_id = v_lect AND library_id = v_lib;
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coordB, 'role', 'authenticated')::text, true);
    EXECUTE 'SET LOCAL ROLE authenticated';
    BEGIN PERFORM public.fn_import_set_export_complet(v_runD, true); v_x := 'accepte';
    EXCEPTION WHEN OTHERS THEN v_x := left(SQLERRM, 20); END;
    v_h := v_h || v_x;
    EXECUTE 'RESET ROLE';
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    -- (le run d'essai, plus récent que le run 2, est archivé : le run 2 reste le fichier actuel)
    UPDATE ingest.partner_catalog_import_runs SET archived_at = now() WHERE id IN (v_runU, v_runD);
    IF v_h[1:4] = ARRAY['error.import.export_complet_after_dispatch', 'error.import.export_complet_after_dispatch',
                   'error.import.export_complet_after_dispatch', 'error.import.deposit_admin_only']
       AND v_h[5] LIKE 'Acesso%' AND v_h[6] = 'Acesso restrito ao c' AND v_h[7] LIKE 'Run %' AND array_length(v_h, 1) = 7
       AND (SELECT export_complet FROM ingest.partner_catalog_import_runs WHERE id = v_run2)
       AND NOT (SELECT export_complet FROM ingest.partner_catalog_import_runs WHERE id = v_runU)
       AND NOT (SELECT export_complet FROM ingest.partner_catalog_import_runs WHERE id = v_runD)
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||array_to_string(v_h, ' / ')); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE';
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T3 ──────────────────────────────────────────────────────────────
  v_t := 'T3 constat : disparus, engages (4 motifs), brouillon ; deplace, reetiquete, autre source, autre bibliotheque, notice absente, rejetee, fait main jamais ; aucune ecriture';
  DECLARE v_b jsonb; v_v jsonb;
  BEGIN
    EXECUTE v_ref INTO v_avant;
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_b := public.fn_import_retraits(v_run2, 200, 0);
    EXECUTE 'RESET ROLE';
    EXECUTE v_ref INTO v_apres;
    SELECT jsonb_object_agg(x->>'exemplar_id', jsonb_build_object('v', x->>'verdict', 'm', x->>'motif', 'n', x->>'draft_nature'))
      INTO v_v FROM jsonb_array_elements(v_b->'items') x;
    IF v_apres = v_avant
       AND v_b->'counts' = jsonb_build_object('disparu', 2, 'disparu_engage', 4, 'disparu_brouillon', 1, 'retire_reapparu', 0,
                                              'hors_fichier', 2, 'retires', 0)
       AND v_v->(e3::text)->>'v' = 'disparu' AND v_v->(e8::text)->>'v' = 'disparu'
       AND v_v->(e9::text)->>'m' = 'pret' AND v_v->(e10::text)->>'m' = 'reservation'
       AND v_v->(e11::text)->>'m' = 'peb' AND v_v->(e12::text)->>'m' = 'consultation'
       AND v_v->(e9::text)->>'v' = 'disparu_engage'
       AND v_v->(e13::text)->>'v' = 'disparu_brouillon' AND v_v->(e13::text)->>'n' = 'autre'
       AND NOT (v_v ?| ARRAY[e14::text, e16::text, e17::text, e18::text, e19::text, e36::text, eB::text, eMain::text])
       AND v_b->>'bloque_retraits' IS NULL AND v_b->>'bloque_levees' IS NULL
       AND (v_b->'seuil'->>'atteint')::boolean = false AND (v_b->'seuil'->>'disparus')::int = 7
       AND (v_b->'seuil'->>'total')::int = 45
       AND (v_b->'proposables'->>'retraits')::int = 2
       AND (v_b->>'export_complet')::boolean AND (v_b->>'items_du_fichier')::int > 0
       AND (SELECT x->>'titulo' FROM jsonb_array_elements(v_b->'items') x WHERE (x->>'exemplar_id')::bigint = e3) IS NOT NULL
       AND v_b->'items'->0->>'verdict' = 'disparu'
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : catalogue '||CASE WHEN v_apres = v_avant THEN 'intact' ELSE 'CHANGE' END
         ||' '||coalesce((v_b - 'items')::text, 'NULL')||' items='||left(coalesce(v_v::text, '∅'), 600)); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T4 ──────────────────────────────────────────────────────────────
  v_t := 'T4 conditions : sans export complet, fichier sans exemplaires, ligne en echec, run en cours ou en echec : rien propose, motif dit';
  DECLARE v_m text[] := ARRAY[]::text[]; v_b jsonb; v_p jsonb; v_runV bigint;
  BEGIN
    -- (a) sans export complet : les disparus se lisent, rien n'est proposé
    BEGIN
      UPDATE ingest.partner_catalog_import_runs SET export_complet = false WHERE id = v_run2;
      EXECUTE 'SET LOCAL ROLE authenticated';
      v_b := public.fn_import_retraits(v_run2, 200, 0);
      v_p := public.fn_import_proposer_retraits(v_run2);
      EXECUTE 'RESET ROLE';
      v_m := v_m || (v_b->>'bloque_retraits') || ((v_b->'counts'->>'disparu') || '/' || (v_p->>'retraits') || '/'
                     || (SELECT count(*) FROM public.exemplar_drafts WHERE import_retrait IS NOT NULL));
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (b) un fichier qui ne décrit aucun exemplaire
    BEGIN
      UPDATE ingest.partner_catalog_staging_rows SET normalized_payload = jsonb_set(normalized_payload, '{items}', '[]'::jsonb)
       WHERE run_id = v_run2;
      EXECUTE 'SET LOCAL ROLE authenticated';
      v_b := public.fn_import_retraits(v_run2, 200, 0);
      v_p := public.fn_import_proposer_retraits(v_run2);
      EXECUTE 'RESET ROLE';
      v_m := v_m || (v_b->>'bloque_retraits') || ((v_b->'counts'->>'disparu') || '/' || (v_p->>'retraits'));
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (c) une ligne en échec d'analyse
    BEGIN
      UPDATE ingest.partner_catalog_staging_rows SET parse_status = 'error' WHERE id = r8;
      EXECUTE 'SET LOCAL ROLE authenticated';
      v_b := public.fn_import_retraits(v_run2, 200, 0);
      v_p := public.fn_import_proposer_retraits(v_run2);
      EXECUTE 'RESET ROLE';
      v_m := v_m || (v_b->>'bloque_retraits') || ((v_b->>'bloque_levees') || '/' || (v_p->>'retraits'));
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (d) run en cours (retraitement), (e) run en échec
    BEGIN
      UPDATE ingest.partner_catalog_import_runs SET run_status = 'processing' WHERE id = v_run2;
      EXECUTE 'SET LOCAL ROLE authenticated';
      v_b := public.fn_import_retraits(v_run2, 200, 0);
      v_p := public.fn_import_proposer_retraits(v_run2);
      EXECUTE 'RESET ROLE';
      v_m := v_m || (v_b->>'bloque_retraits') || (v_p->>'retraits');
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    BEGIN
      UPDATE ingest.partner_catalog_import_runs SET run_status = 'partially_failed' WHERE id = v_run2;
      EXECUTE 'SET LOCAL ROLE authenticated';
      v_b := public.fn_import_retraits(v_run2, 200, 0);
      EXECUTE 'RESET ROLE';
      v_m := v_m || (v_b->>'bloque_retraits');
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    IF v_m = ARRAY['pas_export_complet', '2/0/0', 'fichier_sans_exemplaires', '0/0', 'lignes_en_echec', 'lignes_en_echec/0',
                   'run_en_cours', '0', 'lignes_en_echec']
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||array_to_string(v_m, ' / ')); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T5 ──────────────────────────────────────────────────────────────
  v_t := 'T5 seuil 10 % ET 20 : bloque sans confirmation, propose apres ; 19 disparus et 25 sur 300 proposes directement ; confirmation sans drapeau refusee';
  DECLARE v_m text[] := ARRAY[]::text[]; v_b jsonb; v_p jsonb; v_x text; v_bk bigint; v_hk bigint; v_srcK bigint; v_runK bigint;
  BEGIN
    -- (a) 25 lignes à un exemplaire vidées (≥ 20 et > 10 % de 45)
    BEGIN
      UPDATE ingest.partner_catalog_staging_rows SET normalized_payload = jsonb_set(normalized_payload, '{items}', '[]'::jsonb)
       WHERE run_id = v_run2 AND row_no IN (SELECT s.row_no FROM ingest.partner_catalog_staging_rows s
                                             WHERE s.run_id = v_run2 AND jsonb_array_length(s.normalized_payload->'items') = 1
                                               AND s.row_no NOT IN (15, 16) ORDER BY s.row_no LIMIT 16);
      EXECUTE 'SET LOCAL ROLE authenticated';
      v_b := public.fn_import_retraits(v_run2, 200, 0);
      v_p := public.fn_import_proposer_retraits(v_run2);
      v_m := v_m || (v_b->>'bloque_retraits') || ((v_b->'seuil'->>'disparus') || '/' || (v_b->'seuil'->>'atteint') || '/' || (v_p->>'retraits'));
      v_p := public.fn_import_confirmer_export_complet(v_run2);
      v_b := public.fn_import_retraits(v_run2, 200, 0);
      v_m := v_m || coalesce(v_b->>'bloque_retraits', 'aucun') || ((v_p->>'confirme_par') = v_coord::text)::text;
      v_p := public.fn_import_proposer_retraits(v_run2);
      EXECUTE 'RESET ROLE';
      v_m := v_m || ((v_p->>'retraits') || '/' || (v_b->'counts'->>'disparu'));
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (b) 19 disparus (> 10 %, mais moins de 20) : proposés sans confirmation
    BEGIN
      UPDATE ingest.partner_catalog_staging_rows SET normalized_payload = jsonb_set(normalized_payload, '{items}', '[]'::jsonb)
       WHERE run_id = v_run2 AND row_no IN (SELECT s.row_no FROM ingest.partner_catalog_staging_rows s
                                             WHERE s.run_id = v_run2 AND jsonb_array_length(s.normalized_payload->'items') = 1
                                               AND s.row_no NOT IN (15, 16) ORDER BY s.row_no LIMIT 12);
      EXECUTE 'SET LOCAL ROLE authenticated';
      v_b := public.fn_import_retraits(v_run2, 200, 0);
      EXECUTE 'RESET ROLE';
      v_m := v_m || (coalesce(v_b->>'bloque_retraits', 'aucun') || '/' || (v_b->'seuil'->>'disparus'));
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (c) 25 disparus sur 300 (< 10 %) : proposés sans confirmation
    BEGIN
      INSERT INTO public.books (titulo, bib_ref) VALUES ('L7 trois cents', 'L7-K-REF') RETURNING id INTO v_bk;
      INSERT INTO public.book_holdings (book_id, library_id, loanable) VALUES (v_bk, v_lib, true) RETURNING id INTO v_hk;
      INSERT INTO ingest.partner_catalog_sources (partner_name, library_id, relation_status, source_kind, import_enabled)
      VALUES ('L7 source K', v_lib, 'mapeada', 'own_catalog', true) RETURNING id INTO v_srcK;
      ALTER TABLE public.exemplares DISABLE TRIGGER trg_exemplar_recompute_availability;
      INSERT INTO public.exemplares (bib_ref, tombo, library_id, holding_id, source_item_code, import_source_id, circulation_policy)
      SELECT 'L7-K-REF', 'L7K-' || i, v_lib, v_hk, 'L7K-C-' || i, v_srcK, 'ambos' FROM generate_series(1, 300) i;
      ALTER TABLE public.exemplares ENABLE TRIGGER trg_exemplar_recompute_availability;
      INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status, export_complet)
      VALUES (v_srcK, v_lib, 'essai/l7-k.iso', 'l7-k.iso', 'marc_iso2709', 'ready_for_review', true) RETURNING id INTO v_runK;
      INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, title, normalized_payload, match_status, editorial_decision, proposed_book_id)
      VALUES (v_runK, 1, 'L7-K', 'L7 trois cents',
              jsonb_build_object('items', (SELECT jsonb_agg(jsonb_build_object('source_item_code', 'L7K-C-' || i)) FROM generate_series(26, 300) i)),
              'known_record', 'pending', v_bk);
      EXECUTE 'SET LOCAL ROLE authenticated';
      v_b := public.fn_import_retraits(v_runK, 200, 0);
      EXECUTE 'RESET ROLE';
      v_m := v_m || (coalesce(v_b->>'bloque_retraits', 'aucun') || '/' || (v_b->'seuil'->>'disparus') || '/' || (v_b->'seuil'->>'atteint'));
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (d) la confirmation exige le drapeau
    BEGIN
      UPDATE ingest.partner_catalog_import_runs SET export_complet = false WHERE id = v_run2;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.fn_import_confirmer_export_complet(v_run2); v_x := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_x = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_m := v_m || v_x;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    IF v_m = ARRAY['seuil_non_confirme', '23/true/0', 'aucun', 'true', '18/18', 'aucun/19', 'aucun/25/false',
                   'error.import.export_complet_absent']
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||array_to_string(v_m, ' / ')); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T21 ─────────────────────────────────────────────────────────────
  v_t := 'T21 le fichier actuel de la source : run perime ou archive bloques ; exemplaire ne apres le run jamais disparu';
  DECLARE v_m text[] := ARRAY[]::text[]; v_b jsonb; v_p jsonb; v_run3 bigint; eNew bigint; eNew2 bigint;
  BEGIN
    -- (a) un run plus récent de la source existe (stable) : le run 2 est périmé
    BEGIN
      INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
      VALUES (v_src, v_lib, 'essai/l7-r3.iso', 'l7-r3.iso', 'marc_iso2709', 'drafts_created') RETURNING id INTO v_run3;
      EXECUTE 'SET LOCAL ROLE authenticated';
      v_b := public.fn_import_retraits(v_run2, 200, 0);
      v_p := public.fn_import_proposer_retraits(v_run2);
      EXECUTE 'RESET ROLE';
      v_m := v_m || (coalesce(v_b->>'bloque_retraits', '∅') || '/' || coalesce(v_b->>'bloque_levees', '∅') || '/'
                     || (v_p->>'retraits') || '/' || (v_p->>'levees'));
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (b) le run 2 archivé
    BEGIN
      UPDATE ingest.partner_catalog_import_runs SET archived_at = now() WHERE id = v_run2;
      EXECUTE 'SET LOCAL ROLE authenticated';
      v_b := public.fn_import_retraits(v_run2, 200, 0);
      EXECUTE 'RESET ROLE';
      v_m := v_m || (coalesce(v_b->>'bloque_retraits', '∅') || '/' || coalesce(v_b->>'bloque_levees', '∅'));
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (c) un exemplaire né d'un run postérieur (archivé : le run 2 reste actuel),
    --     un autre créé après le run 2 : jamais disparus, sur une notice du fichier
    BEGIN
      INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status, archived_at)
      VALUES (v_src, v_lib, 'essai/l7-r3b.iso', 'l7-r3b.iso', 'marc_iso2709', 'drafts_created', now()) RETURNING id INTO v_run3;
      INSERT INTO public.exemplares (bib_ref, tombo, library_id, holding_id, source_item_code, source_item_id, import_source_id, import_run_id, circulation_policy)
      SELECT e.bib_ref, 'L7-NEUF-R3', v_lib, e.holding_id, 'L7-NEUF-R3', 'xid-neuf-r3', v_src, v_run3, 'ambos'
        FROM public.exemplares e WHERE e.id = e16 RETURNING id INTO eNew;
      INSERT INTO public.exemplares (bib_ref, tombo, library_id, holding_id, source_item_code, source_item_id, import_source_id, circulation_policy, created_at)
      SELECT e.bib_ref, 'L7-NEUF-2', v_lib, e.holding_id, 'L7-NEUF-2', 'xid-neuf-2', v_src, 'ambos', now() + interval '1 hour'
        FROM public.exemplares e WHERE e.id = e16 RETURNING id INTO eNew2;
      EXECUTE 'SET LOCAL ROLE authenticated';
      v_b := public.fn_import_retraits(v_run2, 200, 0);
      EXECUTE 'RESET ROLE';
      v_m := v_m || (coalesce(v_b->>'bloque_retraits', '∅') || '/' || (v_b->'counts'->>'disparu') || '/'
                     || (EXISTS (SELECT 1 FROM jsonb_array_elements(v_b->'items') x
                                  WHERE (x->>'exemplar_id')::bigint IN (eNew, eNew2)))::text);
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    IF v_m = ARRAY['run_perime/run_perime/0/0', 'run_archive/run_archive', '∅/2/false']
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||array_to_string(v_m, ' / ')); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T6 ──────────────────────────────────────────────────────────────
  v_t := 'T6 proposer : un brouillon par disparu proposable, copie complete, trace, lot ne d''un import retrouve par le run ; second geste : rien';
  DECLARE v_p2 jsonb; v_b jsonb;
  BEGIN
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_res := public.fn_import_proposer_retraits(v_run2);
    v_p2 := public.fn_import_proposer_retraits(v_run2);
    v_b := public.fn_import_retraits(v_run2, 200, 0);
    EXECUTE 'RESET ROLE';
    v_lotR := (v_res->>'batch_id')::bigint;
    SELECT max(id) FILTER (WHERE published_exemplar_id = e3), max(id) FILTER (WHERE published_exemplar_id = e8)
      INTO dR3, dR8 FROM public.exemplar_drafts WHERE import_retrait IS NOT NULL;
    IF (v_res->>'retraits')::int = 2 AND (v_res->>'levees')::int = 0 AND v_lotR IS NOT NULL
       AND (v_res->'ignores'->>'disparu_engage')::int = 4 AND (v_res->'ignores'->>'disparu_brouillon')::int = 1
       AND (v_p2->>'retraits')::int = 0 AND v_p2->>'batch_id' IS NULL
       AND (v_b->'counts'->>'disparu_brouillon')::int = 3 AND (v_b->'counts'->>'disparu')::int = 0
       AND (SELECT x->>'draft_nature' FROM jsonb_array_elements(v_b->'items') x WHERE (x->>'exemplar_id')::bigint = e3) = 'retrait'
       AND public.fn_batch_is_imported(v_lotR)
       AND ingest.fn_h21_lot_ouvert_du_run(v_run2, v_lib) = v_lotR
       AND (SELECT d.batch_id = v_lotR AND d.status = 'draft' AND d.import_staging_row_id IS NULL AND d.target_library_id = v_lib
                   AND d.import_retrait->>'nature' = 'retrait' AND (d.import_retrait->>'run_id')::bigint = v_run2
                   AND (d.import_retrait->>'source_id')::bigint = v_src AND (d.import_retrait->>'book_id')::bigint = b3
                   AND (d.import_retrait->>'holding_id')::bigint = h3 AND (d.import_retrait->>'library_id')::uuid = v_lib
                   AND d.import_retrait->>'proposed_by' = v_coord::text
                   AND d.tombo = e.tombo AND d.label_note = 'L7 etiquette' AND d.shelf_location IS NOT DISTINCT FROM e.shelf_location
                   AND d.source_item_code = e.source_item_code AND d.import_source_id = v_src AND NOT d.retake_untouched
              FROM public.exemplar_drafts d JOIN public.exemplares e ON e.id = d.published_exemplar_id WHERE d.id = dR3)
       AND (SELECT count(*) FROM public.exemplar_drafts WHERE import_retrait IS NOT NULL) = 2
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||coalesce(v_res::text, 'NULL')||' / '||coalesce(v_p2::text, 'NULL')
         ||' / '||coalesce((v_b->'counts')::text, '∅')); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T7 ──────────────────────────────────────────────────────────────
  v_t := 'T7 un seul brouillon vivant : Editer, brouillon de reprise par l''API, retour de corbeille a cote d''un autre : refuses';
  DECLARE v_h1 text; v_h2 text; v_h3 text; v_e8 bigint;
  BEGIN
    EXECUTE 'SET LOCAL ROLE authenticated';
    BEGIN PERFORM public.create_exemplar_draft_from_exemplar(e8, NULL); v_h1 := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h1 = PG_EXCEPTION_HINT; END;
    BEGIN
      INSERT INTO public.exemplar_drafts (published_exemplar_id, action, status, label_status, target_library_id, tombo)
      SELECT e.id, 'update', 'draft', 'pending', v_lib, e.tombo FROM public.exemplares e WHERE e.id = e3;
      v_h2 := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h2 = PG_EXCEPTION_HINT; END;
    EXECUTE 'RESET ROLE';
    -- le retrait à la corbeille, un « Éditer » naît, le retrait ne revient pas
    BEGIN
      UPDATE public.exemplar_drafts SET status = 'cancelled' WHERE id = dR8;
      v_e8 := public.create_exemplar_draft_from_exemplar(e8, NULL);
      BEGIN UPDATE public.exemplar_drafts SET status = 'draft' WHERE id = dR8; v_h3 := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h3 = PG_EXCEPTION_HINT; END;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    IF v_h1 = 'error.catalog.item_retrait_pending' AND v_h2 = 'error.catalog.item_retrait_pending'
       AND v_h3 = 'error.import.item_retrait_superseded'
       AND (SELECT count(*) FROM public.exemplar_drafts WHERE published_exemplar_id IN (e3, e8) AND status IN ('draft', 'ready')) = 2
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||concat_ws(' / ', v_h1, v_h2, v_h3)); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T8 ──────────────────────────────────────────────────────────────
  v_t := 'T8 trace refusee a l''API (brouillon INSERT et UPDATE, exemplaire par la RLS) ; marqueur refuse a toute autre voie (INSERT et UPDATE)';
  DECLARE v_h1 text; v_h2 text; v_h3 text; v_h4 text; v_h5 text; v_n1 int;
  BEGIN
    EXECUTE 'SET LOCAL ROLE authenticated';
    BEGIN
      INSERT INTO public.exemplar_drafts (published_exemplar_id, action, status, label_status, target_library_id, tombo, import_retrait)
      SELECT e.id, 'update', 'draft', 'pending', v_lib, e.tombo, jsonb_build_object('nature', 'retrait', 'run_id', v_run2)
        FROM public.exemplares e WHERE e.id = e14;
      v_h1 := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h1 = PG_EXCEPTION_HINT; END;
    BEGIN
      UPDATE public.exemplar_drafts SET import_retrait = import_retrait || '{"run_id": 1}'::jsonb WHERE id = dR3;
      v_h2 := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h2 = PG_EXCEPTION_HINT; END;
    BEGIN
      UPDATE public.exemplar_drafts SET published_exemplar_id = e14 WHERE id = dR3;
      v_h3 := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h3 = PG_EXCEPTION_HINT; END;
    -- l'exemplaire : aucune politique d'écriture pour l'API
    UPDATE public.exemplares SET retire_at = now() WHERE id = e14;
    GET DIAGNOSTICS v_n1 = ROW_COUNT;
    EXECUTE 'RESET ROLE';
    -- toute autre voie (une fonction, postgres) : refusée
    BEGIN UPDATE public.exemplares SET retire_at = now() WHERE id = e14; v_h4 := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h4 = PG_EXCEPTION_HINT; END;
    BEGIN
      INSERT INTO public.exemplares (bib_ref, tombo, library_id, holding_id, retire_at)
      SELECT e.bib_ref, 'L7-MARQUE-1', e.library_id, e.holding_id, now() FROM public.exemplares e WHERE e.id = e14;
      v_h5 := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h5 = PG_EXCEPTION_HINT; END;
    IF v_h1 = 'error.import.item_retrait_trace_reserved' AND v_h2 = 'error.import.item_retrait_trace_reserved'
       AND v_h3 = 'error.import.item_retrait_trace_reserved' AND v_n1 = 0
       AND v_h4 = 'error.import.item_retrait_reserved' AND v_h5 = 'error.import.item_retrait_reserved'
       AND (SELECT retire_at IS NULL FROM public.exemplares WHERE id = e14)
       AND (SELECT published_exemplar_id = e3 AND (import_retrait->>'run_id')::bigint = v_run2 FROM public.exemplar_drafts WHERE id = dR3)
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||concat_ws(' / ', v_h1, v_h2, v_h3, v_n1::text, v_h4, v_h5)); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T9 ──────────────────────────────────────────────────────────────
  v_t := 'T9 droits : lectrice, librarian, autre bibliotheque refusees (constat, proposition, confirmation) ; anon sans droit ; aides fermees';
  DECLARE v_m text[] := ARRAY[]::text[]; v_x text; u uuid; f text;
  BEGIN
    FOREACH u IN ARRAY ARRAY[v_lect, v_lect, v_coordB] LOOP
      IF array_length(v_m, 1) = 3 THEN
        UPDATE public.user_library_memberships SET role = 'librarian' WHERE user_id = v_lect AND library_id = v_lib;
      END IF;
      PERFORM set_config('request.jwt.claims', json_build_object('sub', u, 'role', 'authenticated')::text, true);
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.fn_import_retraits(v_run2, 200, 0); v_x := 'accepte';
      EXCEPTION WHEN OTHERS THEN v_x := left(SQLERRM, 12); END;
      v_m := v_m || v_x;
      BEGIN PERFORM public.fn_import_proposer_retraits(v_run2); v_x := 'accepte';
      EXCEPTION WHEN OTHERS THEN v_x := left(SQLERRM, 12); END;
      v_m := v_m || v_x;
      BEGIN PERFORM public.fn_import_confirmer_export_complet(v_run2); v_x := 'accepte';
      EXCEPTION WHEN OTHERS THEN v_x := left(SQLERRM, 12); END;
      v_m := v_m || v_x;
      EXECUTE 'RESET ROLE';
    END LOOP;
    UPDATE public.user_library_memberships SET role = 'reader' WHERE user_id = v_lect AND library_id = v_lib;
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    FOREACH f IN ARRAY ARRAY['public.fn_import_set_export_complet(bigint, boolean)', 'public.fn_import_confirmer_export_complet(bigint)',
                             'public.fn_import_retraits(bigint, integer, integer)', 'public.fn_import_proposer_retraits(bigint)'] LOOP
      IF has_function_privilege('anon', f, 'EXECUTE') OR NOT has_function_privilege('authenticated', f, 'EXECUTE') THEN
        v_m := v_m || ('droit ' || f);
      END IF;
    END LOOP;
    FOREACH f IN ARRAY ARRAY['ingest.fn_h21_retraits_constat(bigint, boolean, boolean)', 'ingest.fn_h21_retraits_bilan(bigint, boolean, integer, integer)',
                             'ingest.fn_h21_publier_retrait(bigint, boolean)', 'ingest.fn_h21_retrait_engage(bigint)',
                             'ingest.fn_h21_acces_retraits(bigint)', 'public.tg_exemplares_marqueur_retrait()'] LOOP
      IF has_function_privilege('authenticated', f, 'EXECUTE') OR has_function_privilege('anon', f, 'EXECUTE') THEN
        v_m := v_m || ('aide ' || f);
      END IF;
    END LOOP;
    IF array_length(v_m, 1) = 9
       AND v_m[1] LIKE 'Acesso%' AND v_m[2] LIKE 'Acesso%' AND v_m[3] LIKE 'Acesso%'
       AND v_m[4:6] = ARRAY['Acesso restr', 'Acesso restr', 'Acesso restr']
       AND v_m[7] LIKE 'Run %' AND v_m[8] LIKE 'Run %' AND v_m[9] LIKE 'Run %'
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||array_to_string(v_m, ' / ')); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE';
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T10 ─────────────────────────────────────────────────────────────
  v_t := 'T10 revision obligatoire ; rapport : retraits proposes, disparus engages, seuil et confirmation';
  DECLARE v_h text; v_rap jsonb;
  BEGIN
    EXECUTE 'SET LOCAL ROLE authenticated';
    BEGIN PERFORM public.publish_exemplar_draft(dR3); v_h := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
    EXECUTE 'RESET ROLE';
    v_rap := public.fn_batch_review_report(v_lotR);
    -- le brouillon du rang 8 sort du lot avant la demande : il y reviendra
    -- après l'approbation (T11, ajouté après la révision)
    UPDATE public.exemplar_drafts SET batch_id = NULL WHERE id = dR8;
    v_res := public.fn_batch_review_request(v_lotR, NULL);
    v_rev := (v_res->>'review_id')::bigint;
    IF v_h = 'error.publish.review_required'
       AND (v_rap->'retraits'->>'count')::int = 2 AND (v_rap->'retraits'->>'retraits')::int = 2
       AND (v_rap->'retraits'->>'levees')::int = 0 AND (v_rap->'retraits'->>'published')::int = 0
       AND EXISTS (SELECT 1 FROM jsonb_array_elements(v_rap->'retraits'->'examples') x
                    WHERE (x->>'item_draft_id')::bigint = dR3 AND (x->>'exemplar_id')::bigint = e3
                      AND x->>'nature' = 'retrait' AND x->>'titulo' IS NOT NULL)
       AND (v_rap->'retraits'->'runs'->0->>'run_id')::bigint = v_run2
       AND (v_rap->'retraits'->'runs'->0->'bilan'->'counts'->>'disparu_engage')::int = 4
       AND (v_rap->'retraits'->'runs'->0->'bilan'->'seuil'->>'atteint')::boolean = false
       AND (v_rap->'retraits'->'runs'->0->'bilan'->>'confirme')::boolean = false
       AND jsonb_array_length(v_rap->'retraits'->'runs'->0->'engages') = 4
       AND EXISTS (SELECT 1 FROM jsonb_array_elements(v_rap->'retraits'->'runs'->0->'engages') x
                    WHERE (x->>'exemplar_id')::bigint = e10 AND x->>'motif' = 'reservation')
       AND coalesce((v_rap->'items'->>'count')::int, 0) = 0
       AND v_rev IS NOT NULL
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : avant revision='||coalesce(v_h, '∅')
         ||' rapport='||left(coalesce((v_rap->'retraits')::text, 'NULL'), 600)); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;
  IF v_rev IS NOT NULL THEN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
    PERFORM public.fn_batch_review_verdict(v_rev, 'approved', NULL);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
  END IF;
  UPDATE public.exemplar_drafts SET batch_id = v_lotR WHERE id = dR8;

  -- ── T11 ─────────────────────────────────────────────────────────────
  -- Chaque refus est essayé dans un sous-bloc annulé (sentinelle).
  v_t := 'T11 refus a la publication : supprime, bibliotheque, notice, fonds, source, run, run instable, deja retire, engage, revenu, notice sortie, export ote, effet de bord, apres revision, autre bibliotheque, par le lot';
  DECLARE v_h text; v_hs text[] := ARRAY[]::text[]; v_cnt int; v_hx bigint; v_ok boolean := true;
  BEGIN
    -- (a) exemplaire supprimé : le lien tombe ; jamais une création
    BEGIN
      DELETE FROM public.exemplares WHERE id = e3;
      v_cnt := (SELECT count(*) FROM public.exemplares);
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(dR3); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || (v_h || CASE WHEN (SELECT count(*) FROM public.exemplares) = v_cnt THEN '' ELSE '+CREATION' END);
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (b) la cible du brouillon réattribuée à B (l'administration publie)
    BEGIN
      UPDATE public.exemplar_drafts SET target_library_id = v_libB WHERE id = dR3;
      PERFORM set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(dR3); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    -- (c) déplacé vers une autre notice
    BEGIN
      UPDATE public.exemplares SET holding_id = (SELECT e.holding_id FROM public.exemplares e WHERE e.id = e14) WHERE id = e3;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(dR3); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (d) la cible de fonds du brouillon
    BEGIN
      UPDATE public.exemplar_drafts SET target_holding_id = (SELECT e.holding_id FROM public.exemplares e WHERE e.id = e14) WHERE id = dR3;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(dR3); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (e) la source de l'exemplaire
    BEGIN
      UPDATE public.exemplares SET import_source_id = v_src2 WHERE id = e3;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(dR3); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (f) le run de la trace n'existe plus
    BEGIN
      UPDATE public.exemplar_drafts SET import_retrait = jsonb_set(import_retrait, '{run_id}', '-1') WHERE id = dR3;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(dR3); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (g) le run en cours de retraitement ; (h) une ligne en échec
    BEGIN
      UPDATE ingest.partner_catalog_import_runs SET run_status = 'processing' WHERE id = v_run2;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(dR3); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    BEGIN
      UPDATE ingest.partner_catalog_staging_rows SET parse_status = 'error' WHERE id = r8;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(dR3); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (i) déjà retiré
    BEGIN
      PERFORM set_config('anarbib.h21_marqueur_retrait', 'on', true);
      UPDATE public.exemplares SET retire_at = now() WHERE id = e3;
      PERFORM set_config('anarbib.h21_marqueur_retrait', '', true);
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(dR3); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (j) engagé entre-temps : un prêt ; (k) une réservation au niveau du fonds
    BEGIN
      INSERT INTO public.emprestimo_itens_v2 (emprestimo_id, line_no, sub_id, book_id, item_id, holding_id, bib_ref, due_at)
      SELECT v_emp, 2, v_emp || '.2', b3, e.id, e.holding_id, e.bib_ref, current_date + 30 FROM public.exemplares e WHERE e.id = e3;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(dR3); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    BEGIN
      INSERT INTO public.reserva_linhas_v2 (reserva_id, line_no, book_id, item_id, holding_id, bib_ref)
      SELECT v_resv, 2, b3, NULL, e.holding_id, e.bib_ref FROM public.exemplares e WHERE e.id = e3;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(dR3); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || (v_h || CASE WHEN (SELECT count(*) FROM public.reserva_linhas_v2 WHERE reserva_id = v_resv AND item_status = 'ativa') = 2
                                   THEN '' ELSE '+ANNULEE' END);
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (l) revenu dans le fichier : par son code ; (m) par son expl_id
    BEGIN
      UPDATE ingest.partner_catalog_staging_rows SET normalized_payload = jsonb_set(normalized_payload, '{items}',
               (normalized_payload->'items') || jsonb_build_array(jsonb_build_object('source_item_code', '33700003413727')))
       WHERE run_id = v_run2 AND row_no = 20;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(dR3); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    BEGIN
      UPDATE ingest.partner_catalog_staging_rows SET normalized_payload = jsonb_set(normalized_payload, '{items}',
               (normalized_payload->'items') || jsonb_build_array(jsonb_build_object('source_item_code', 'L7-AUTRE-CODE', 'source_item_id', '3')))
       WHERE run_id = v_run2 AND row_no = 20;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(dR3); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (n) la notice sortie du fichier (sa ligne rejetée par choix)
    BEGIN
      UPDATE ingest.partner_catalog_staging_rows SET editorial_decision = 'reject', editorial_note = 'L7 ecartee' WHERE id = r3;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(dR3); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (o) l'export complet ôté (filet)
    BEGIN
      UPDATE ingest.partner_catalog_import_runs SET export_complet = false WHERE id = v_run2;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(dR3); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (p) effet de bord : une écriture parasite à la pose (un déclencheur
    --     d'essai, annulé avec le sous-bloc, réécrit la note)
    BEGIN
      EXECUTE $x$CREATE FUNCTION public.zz_h21l7_parasite() RETURNS trigger LANGUAGE plpgsql AS
                 $p$BEGIN NEW.notes := 'L7 parasite'; RETURN NEW; END$p$ $x$;
      EXECUTE 'CREATE TRIGGER zz_h21l7_parasite BEFORE UPDATE OF retire_at ON public.exemplares
                 FOR EACH ROW EXECUTE FUNCTION public.zz_h21l7_parasite()';
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(dR3); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (q) ajouté au lot après la révision
    BEGIN
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(dR8); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (r) une autre bibliothèque
    BEGIN
      PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coordB, 'role', 'authenticated')::text, true);
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(dR3); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    -- (s0) un fichier plus récent de la source (stable, non archivé) : supplanté
    DECLARE v_run3 bigint;
    BEGIN
      INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
      VALUES (v_src, v_lib, 'essai/l7-r3c.iso', 'l7-r3c.iso', 'marc_iso2709', 'ready_for_review') RETURNING id INTO v_run3;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(dR3); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (s1) un fichier plus récent, archivé, décrit l'exemplaire
    DECLARE v_run3 bigint;
    BEGIN
      INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status, archived_at)
      VALUES (v_src, v_lib, 'essai/l7-r3d.iso', 'l7-r3d.iso', 'marc_iso2709', 'ready_for_review', now()) RETURNING id INTO v_run3;
      INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, title, normalized_payload, match_status, editorial_decision)
      VALUES (v_run3, 1, 'L7-R3D', 'L7 r3d', jsonb_build_object('items', jsonb_build_array(jsonb_build_object('source_item_code', '33700003413727'))),
              'new_record', 'pending');
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(dR3); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (s2) le run du brouillon archivé depuis la proposition : supplanté
    BEGIN
      UPDATE ingest.partner_catalog_import_runs SET archived_at = now() WHERE id = v_run2;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(dR3); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (s) par le lot : l'exemplaire en prêt fait refuser le lot entier, rien posé
    BEGIN
      UPDATE public.exemplar_drafts SET batch_id = NULL WHERE id = dR8;
      INSERT INTO public.emprestimo_itens_v2 (emprestimo_id, line_no, sub_id, book_id, item_id, holding_id, bib_ref, due_at)
      SELECT v_emp, 2, v_emp || '.2', b3, e.id, e.holding_id, e.bib_ref, current_date + 30 FROM public.exemplares e WHERE e.id = e3;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_catalog_batch(v_lotR); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || (v_h || CASE WHEN EXISTS (SELECT 1 FROM public.exemplares WHERE retire_at IS NOT NULL) THEN '+POSE' ELSE '' END);
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    IF v_hs = ARRAY['error.publish.item_retrait_gone', 'error.publish.item_retrait_library_changed',
                    'error.publish.item_retrait_moved', 'error.publish.item_retrait_moved',
                    'error.publish.item_retrait_source_changed', 'error.publish.item_retrait_run_gone',
                    'error.publish.item_retrait_run_unstable', 'error.publish.item_retrait_run_unstable',
                    'error.publish.item_retrait_already_retired', 'error.publish.item_retrait_engaged',
                    'error.publish.item_retrait_engaged', 'error.publish.item_retrait_back_in_file',
                    'error.publish.item_retrait_back_in_file', 'error.publish.item_retrait_notice_absent',
                    'error.import.export_complet_absent', 'error.publish.item_retrait_side_effect',
                    'error.publish.added_after_review', 'error.publish.other_library',
                    'error.publish.item_retrait_run_superseded', 'error.publish.item_retrait_in_newer_file',
                    'error.publish.item_retrait_run_superseded', 'error.publish.item_retrait_engaged']
       AND (SELECT retire_at IS NULL FROM public.exemplares WHERE id = e3)
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||array_to_string(v_hs, ' / ')); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE';
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T12 ─────────────────────────────────────────────────────────────
  v_t := 'T12 publication : le marqueur seul (tout le reste intact), comptes du fonds, trace, journal';
  DECLARE v_x bigint; v_hold text;
  BEGIN
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_x := public.publish_exemplar_draft(dR3);
    EXECUTE 'RESET ROLE';
    EXECUTE v_ref INTO v_apres;
    v_hold := (SELECT string_agg(h.id || ':' || h.exemplares_total || '/' || h.available_count, ',' ORDER BY h.id)
                 FROM public.book_holdings h WHERE h.id <> h3);
    IF v_x = e3 AND v_apres = v_avant AND v_hold = v_hold_avant
       AND (SELECT e.retire_at IS NOT NULL AND e.retire_run_id = v_run2
                   AND (e.retire_trace->>'draft_id')::bigint = dR3 AND (e.retire_trace->>'source_id')::bigint = v_src
                   AND e.retire_trace->>'retire_by' = v_coord::text
              FROM public.exemplares e WHERE e.id = e3)
       AND (SELECT h.exemplares_total = 0 AND h.available_count = 0 FROM public.book_holdings h WHERE h.id = h3)
       AND (SELECT available_count FROM public.books WHERE id = b3) = 0
       AND (SELECT d.status = 'published' AND d.import_retrait->'publication'->>'published_by' = v_coord::text
              FROM public.exemplar_drafts d WHERE d.id = dR3)
       AND EXISTS (SELECT 1 FROM public.catalog_audit_log a WHERE a.action = 'import_retrait_pose' AND a.entity_id = e3
                     AND a.entity_type = 'exemplar' AND a.actor_id = v_coord)
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : reste '||CASE WHEN v_apres = v_avant THEN 'intact' ELSE 'CHANGE' END
         ||' fonds '||CASE WHEN v_hold = v_hold_avant THEN 'intacts' ELSE 'CHANGES' END
         ||' '||coalesce((SELECT to_jsonb(e) - 'label_note' FROM public.exemplares e WHERE e.id = e3)::text, '∅')); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T13 ─────────────────────────────────────────────────────────────
  v_t := 'T13 republication refusee, rien ne bouge ; le constat ne compte plus le retire parmi les disparus';
  DECLARE v_h text; v_avant13 text; v_b13 jsonb;
  BEGIN
    v_avant13 := (SELECT md5(to_jsonb(e)::text) FROM public.exemplares e WHERE e.id = e3);
    EXECUTE 'SET LOCAL ROLE authenticated';
    BEGIN PERFORM public.publish_exemplar_draft(dR3); v_h := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
    -- le retiré, toujours absent du fichier, n'est plus un disparu (ni compté au seuil)
    v_b13 := public.fn_import_retraits(v_run2, 200, 0);
    EXECUTE 'RESET ROLE';
    IF v_h = 'error.publish.item_retrait_already_published'
       AND (SELECT md5(to_jsonb(e)::text) FROM public.exemplares e WHERE e.id = e3) = v_avant13
       AND (v_b13->'counts'->>'disparu')::int = 0 AND (v_b13->'counts'->>'retires')::int = 1
       AND (v_b13->'seuil'->>'disparus')::int = 6
       AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_b13->'items') x WHERE (x->>'exemplar_id')::bigint = e3)
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||coalesce(v_h, '∅')); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T14 ─────────────────────────────────────────────────────────────
  v_t := 'T14 circulation : ni pret, ni reservation, ni conversion, ni consultation, ni PEB (recherche, ajout, creation)';
  DECLARE v_m text[] := ARRAY[]::text[]; v_x text; v_r bigint; v_l bigint; v_tombo text; v_n0 int; v_n1 int;
  BEGIN
    v_tombo := (SELECT tombo FROM public.exemplares WHERE id = e3);
    v_n0 := (SELECT count(*) FROM public.emprestimo_itens_v2) + (SELECT count(*) FROM public.reserva_linhas_v2)
            + (SELECT count(*) FROM public.consulta_linhas_v2) + (SELECT count(*) FROM public.interlibrary_loan_items_v2);
    -- (a) prêt (la coordination, pour la lectrice)
    EXECUTE 'SET LOCAL ROLE authenticated';
    BEGIN PERFORM public.fn_v2_create_emprestimo_by_holdings(v_lect, ARRAY[h3], NULL, 'L7'); v_x := 'accepte';
    EXCEPTION WHEN OTHERS THEN v_x := left(SQLERRM, 26); END;
    v_m := v_m || v_x;
    EXECUTE 'RESET ROLE';
    -- (b) réservation (la lectrice)
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_lect, 'role', 'authenticated')::text, true);
    EXECUTE 'SET LOCAL ROLE authenticated';
    BEGIN PERFORM public.fn_v2_create_reserva_by_holdings(v_lect, ARRAY[h3], NULL, 'L7'); v_x := 'accepte';
    EXCEPTION WHEN OTHERS THEN v_x := left(SQLERRM, 33); END;
    v_m := v_m || v_x;
    EXECUTE 'RESET ROLE';
    -- (c) consultation (compte du fonds périmé à la main : le résolveur décide)
    BEGIN
      UPDATE public.book_holdings SET available_count = 1 WHERE id = h3;
      -- une règle de consultation (le seed n'en pose pas), annulée avec le sous-bloc
      INSERT INTO public.library_circulation_policy_rules (policy_set_id, rule_label, circulation_mode, consultation_allowed)
      SELECT s.id, 'L7 consultation', 'local_consultation', true
        FROM public.library_circulation_policy_sets s WHERE s.library_id = v_lib AND s.is_active ORDER BY s.id DESC LIMIT 1;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.fn_v2_create_consulta_local_by_holdings(v_lect, ARRAY[h3], NULL, 'L7'); v_x := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_x = PG_EXCEPTION_HINT;
        IF coalesce(v_x, '') = '' THEN v_x := SQLERRM; END IF; END;
      EXECUTE 'RESET ROLE';
      v_m := v_m || coalesce(v_x, '∅');
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    -- (d) une réservation au niveau du fonds ne se convertit pas sur lui
    BEGIN
      INSERT INTO public.reservas_v2 (user_id, library_id, status_global) VALUES (v_lect, v_lib, 'ativa') RETURNING id INTO v_r;
      INSERT INTO public.reserva_linhas_v2 (reserva_id, line_no, book_id, item_id, holding_id, bib_ref)
      SELECT v_r, 1, b3, NULL, h3, e.bib_ref FROM public.exemplares e WHERE e.id = e3;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.fn_v2_convert_reserva_linhas_to_emprestimo(v_r, ARRAY[1], NULL, 'L7'); v_x := 'accepte';
      EXCEPTION WHEN OTHERS THEN v_x := left(SQLERRM, 36); END;
      EXECUTE 'RESET ROLE';
      v_m := v_m || v_x;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (d1) la ligne désigne l'exemplaire retiré ; (d2) la ligne n'a que la
    --      référence (le fonds se retrouve par la passerelle)
    BEGIN
      INSERT INTO public.reservas_v2 (user_id, library_id, status_global) VALUES (v_lect, v_lib, 'ativa') RETURNING id INTO v_r;
      INSERT INTO public.reserva_linhas_v2 (reserva_id, line_no, book_id, item_id, holding_id, bib_ref)
      SELECT v_r, 1, b3, e.id, h3, e.bib_ref FROM public.exemplares e WHERE e.id = e3;
      INSERT INTO public.reserva_linhas_v2 (reserva_id, line_no, book_id, item_id, holding_id, bib_ref)
      SELECT v_r, 2, b3, NULL, NULL, e.bib_ref FROM public.exemplares e WHERE e.id = e3;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.fn_v2_convert_reserva_linhas_to_emprestimo(v_r, ARRAY[1], NULL, 'L7'); v_x := 'accepte';
      EXCEPTION WHEN OTHERS THEN v_x := left(SQLERRM, 36); END;
      v_m := v_m || v_x;
      BEGIN PERFORM public.fn_v2_convert_reserva_linhas_to_emprestimo(v_r, ARRAY[2], NULL, 'L7'); v_x := 'accepte';
      EXCEPTION WHEN OTHERS THEN v_x := left(SQLERRM, 36); END;
      v_m := v_m || v_x;
      EXECUTE 'RESET ROLE';
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (d3) deux exemplaires dans le fonds, le retiré a l'id le plus bas : le prêt
    --      prend l'autre (les DEUX choix d'exemplaire du prêt filtrent)
    DECLARE e3b bigint; v_pris bigint;
    BEGIN
      INSERT INTO public.exemplares (bib_ref, tombo, library_id, holding_id, circulation_policy)
      SELECT e.bib_ref, 'L7-T-DEUX', v_lib, h3, 'ambos' FROM public.exemplares e WHERE e.id = e3 RETURNING id INTO e3b;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.fn_v2_create_emprestimo_by_holdings(v_lect, ARRAY[h3], NULL, 'L7'); v_x := 'accepte';
      EXCEPTION WHEN OTHERS THEN v_x := left(SQLERRM, 60); END;
      EXECUTE 'RESET ROLE';
      SELECT max(i.item_id) INTO v_pris FROM public.emprestimo_itens_v2 i WHERE i.holding_id = h3 AND i.item_status = 'aberto';
      v_m := v_m || (v_x || '/' || CASE WHEN v_pris = e3b THEN 'autre' WHEN v_pris = e3 THEN 'RETIRE' ELSE coalesce(v_pris::text, 'aucun') END);
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (e) recherche PEB : absent ; un exemplaire non retiré, lui, est trouvé
    v_m := v_m || (((SELECT count(*) FROM public.fn_peb_search_exemplares(v_tombo, v_lib)) = 0)::text || '/'
                   || ((SELECT count(*) FROM public.fn_peb_search_exemplares(
                          (SELECT x.tombo FROM public.exemplares x WHERE x.id = e16), v_lib)) >= 1)::text);
    -- (f) ajout à un PEB ; (g) création d'un PEB avec lui
    BEGIN
      INSERT INTO public.interlibrary_loans_v2 (lender_library_id, borrower_library_id, initiated_by_library_id, status_global)
      VALUES (v_lib, v_libB, v_lib, 'preparacao') RETURNING id INTO v_l;
      BEGIN PERFORM public.fn_v2_add_emprestimo_interbibliotecas_itens(v_l, ARRAY[e3], NULL, 'L7'); v_x := 'accepte';
      EXCEPTION WHEN OTHERS THEN v_x := left(SQLERRM, 23); END;
      v_m := v_m || v_x;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    BEGIN PERFORM public.fn_peb_create_loan_with_items(
            jsonb_build_object('lender_library_id', v_lib, 'borrower_library_id', v_libB, 'initiated_by_library_id', v_lib),
            jsonb_build_array(jsonb_build_object('line_no', 1, 'holding_id', h3, 'item_id', e3, 'bib_ref', 'L7')));
          v_x := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_x = PG_EXCEPTION_HINT; END;
    v_m := v_m || v_x;
    v_n1 := (SELECT count(*) FROM public.emprestimo_itens_v2) + (SELECT count(*) FROM public.reserva_linhas_v2)
            + (SELECT count(*) FROM public.consulta_linhas_v2) + (SELECT count(*) FROM public.interlibrary_loan_items_v2);
    IF v_m = ARRAY['Nenhum exemplar disponível', 'Sem exemplares disponíveis para r',
                   'error.consulta.no_consultable_copy', 'Nenhum exemplar disponível para conv',
                   'Nenhum exemplar disponível para conv', 'Nenhum exemplar disponível para conv', 'accepte/autre', 'true/true',
                   'Exemplar(es) indisponív', 'error.circulation.item_retired']
       AND v_n1 = v_n0
       AND NOT EXISTS (SELECT 1 FROM public.emprestimo_itens_v2 WHERE item_id = e3)
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||array_to_string(v_m, ' / ')||' lignes '||v_n0||'->'||v_n1); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE';
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T15 ─────────────────────────────────────────────────────────────
  v_t := 'T15 OPAC anon (notice sans exemplaire), RLS (anon, lectrice, B : non ; staff, admin : oui), export (995 absente), recolement (retire, pas manquant)';
  DECLARE v_m text[] := ARRAY[]::text[]; v_x int; v_s jsonb; v_sc jsonb; v_f jsonb; v_ac int; u uuid; v_s2 jsonb; v_f2 jsonb;
  BEGIN
    REFRESH MATERIALIZED VIEW public.mv_books_catalog_list_v1;
    EXECUTE 'SET LOCAL ROLE anon';
    PERFORM set_config('request.jwt.claims', json_build_object('role', 'anon')::text, true);
    v_m := v_m || ((SELECT count(*) FROM api.catalog_list_anon_v1 WHERE book_id = b3)::text || '/'
                   || (SELECT count(*) FROM public.exemplares WHERE id = e3)::text);
    EXECUTE 'RESET ROLE';
    FOREACH u IN ARRAY ARRAY[v_lect, v_coordB, v_coord, v_admin] LOOP
      PERFORM set_config('request.jwt.claims', json_build_object('sub', u, 'role', 'authenticated')::text, true);
      EXECUTE 'SET LOCAL ROLE authenticated';
      SELECT count(*) INTO v_x FROM public.exemplares WHERE id = e3;
      EXECUTE 'RESET ROLE';
      v_m := v_m || v_x::text;
    END LOOP;
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    -- la notice reste au catalogue pour le staff
    v_m := v_m || (SELECT count(*) FROM public.books WHERE id = b3)::text;
    -- l'export : la notice sort, sans son exemplaire retiré
    v_res := public.fn_export_catalog_lote(v_lib, b3 - 1, 1);
    v_m := v_m || (coalesce(jsonb_array_length(v_res->'records'->0->'items'), 0)::text || '/' || v_export_avant::text
                   || '/' || ((v_res->'records'->0->>'id')::bigint = b3)::text);
    -- le récolement
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_s := api.recolement_start(v_lib);
    v_sc := api.recolement_scan((v_s->>'session_id')::uuid, e3);
    v_f := api.recolement_finish((v_s->>'session_id')::uuid);
    -- une seconde session où le retiré n'est PAS scanné : ni manquant, retiré non trouvé
    v_s2 := api.recolement_start(v_lib);
    v_f2 := api.recolement_finish((v_s2->>'session_id')::uuid);
    EXECUTE 'RESET ROLE';
    v_ac := (SELECT count(*) FROM public.exemplares WHERE library_id = v_lib AND retire_at IS NULL);
    v_m := v_m || (((v_s->>'acervo_count')::int = v_ac)::text || '/' || (v_sc->>'retire') || '/'
                   || (EXISTS (SELECT 1 FROM jsonb_array_elements(v_f->'retired') x WHERE (x->>'exemplar_id')::bigint = e3 AND (x->>'scanned')::boolean))::text
                   || '/' || (NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_f->'missing') x WHERE (x->>'exemplar_id')::bigint = e3))::text
                   || '/' || (v_f->>'intrus_count') || '/' || (v_f->>'retired_count') || '/' || ((v_f->>'missing_count')::int = v_ac)::text);
    v_m := v_m || ((NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_f2->'missing') x WHERE (x->>'exemplar_id')::bigint = e3))::text || '/'
                   || (EXISTS (SELECT 1 FROM jsonb_array_elements(v_f2->'retired') x WHERE (x->>'exemplar_id')::bigint = e3 AND NOT (x->>'scanned')::boolean))::text
                   || '/' || (jsonb_array_length(v_f2->'missing') = v_ac)::text);
    IF v_m = ARRAY['0/0', '0', '0', '1', '1', '1', '0/1/true', 'true/true/true/true/0/1/true', 'true/true/true']
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||array_to_string(v_m, ' / ')); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE';
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T22 ─────────────────────────────────────────────────────────────
  v_t := 'T22 un retire ne se supprime pas (exemplaire, notice en cascade) et ne se reattribue pas (deux voies)';
  DECLARE v_m text[] := ARRAY[]::text[]; v_x text;
  BEGIN
    EXECUTE 'SET LOCAL ROLE authenticated';
    BEGIN PERFORM public.discard_exemplar(e3); v_x := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_x = PG_EXCEPTION_HINT; END;
    v_m := v_m || v_x;
    BEGIN PERFORM public.discard_book_cascade(b3); v_x := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_x = PG_EXCEPTION_HINT; END;
    v_m := v_m || v_x;
    EXECUTE 'RESET ROLE';
    BEGIN
      UPDATE public.libraries SET catalog_mode = 'network_published' WHERE id = v_libB;
      PERFORM set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.network_admin_reassign_book_to_library(b3, v_libB); v_x := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_x = PG_EXCEPTION_HINT; END;
      v_m := v_m || coalesce(nullif(v_x, ''), 'sans indice');
      BEGIN PERFORM public.network_admin_reassign_book_from_to_library(b3, v_lib, v_libB); v_x := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_x = PG_EXCEPTION_HINT; END;
      v_m := v_m || coalesce(nullif(v_x, ''), 'sans indice');
      EXECUTE 'RESET ROLE';
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    IF v_m = ARRAY['error.catalog.discard.retired', 'error.catalog.discard.retired',
                   'error.catalog.item_retired_no_reassign', 'error.catalog.item_retired_no_reassign']
       AND (SELECT library_id = v_lib AND retire_at IS NOT NULL FROM public.exemplares WHERE id = e3)
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||array_to_string(v_m, ' / ')); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE';
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T16 ─────────────────────────────────────────────────────────────
  v_t := 'T16 une fusion de brouillons de notice n''emporte pas un brouillon de retrait';
  DECLARE v_s bigint; v_l bigint; v_h text; v_x int; v_lot bigint;
  BEGIN
    BEGIN
      INSERT INTO public.catalog_batches (name, created_by, library_id) VALUES ('L7 fusion', v_coord, v_lib) RETURNING id INTO v_lot;
      INSERT INTO public.book_drafts (batch_id, action, status, titulo, bib_ref, owner_library_id, created_by, updated_by)
      VALUES (v_lot, 'create', 'draft', 'L7 survivant', 'L7-SURV', v_lib, v_coord, v_coord) RETURNING id INTO v_s;
      INSERT INTO public.book_drafts (batch_id, action, status, titulo, bib_ref, owner_library_id, created_by, updated_by)
      VALUES (v_lot, 'create', 'draft', 'L7 perdant', 'L7-PERD', v_lib, v_coord, v_coord) RETURNING id INTO v_l;
      UPDATE public.exemplar_drafts SET batch_id = v_lot, target_bib_ref = 'L7-PERD' WHERE id = dR8;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM api.merge_book_drafts(v_s, v_l, '{}'::jsonb); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_x := (SELECT CASE WHEN target_bib_ref = 'L7-PERD' THEN 1 ELSE 0 END FROM public.exemplar_drafts WHERE id = dR8);
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    IF v_h = 'error.import.item_update_not_mergeable' AND v_x = 1
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||coalesce(v_h, '∅')); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T17 ─────────────────────────────────────────────────────────────
  v_t := 'T17 le run supprime : le retrait reste (retire_at), seul le lien tombe (jamais de renaissance)';
  DECLARE v_ok boolean;
  BEGIN
    BEGIN
      DELETE FROM ingest.partner_catalog_import_runs WHERE id = v_run2;
      v_ok := (SELECT retire_at IS NOT NULL AND retire_run_id IS NULL FROM public.exemplares WHERE id = e3)
              AND (SELECT exemplares_total FROM public.book_holdings WHERE id = h3) = 0;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    IF v_ok THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||coalesce(v_ok::text, '∅')); END IF;
  EXCEPTION WHEN OTHERS THEN v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T18 ─────────────────────────────────────────────────────────────
  v_t := 'T18 levee : reapparu (deja la) et reetiquete proposes sans export complet ; refus (sorti du fichier, deja leve) ; publiee : pretable, compte, vu';
  DECLARE v_b jsonb; v_p jsonb; v_h text; v_hs text[] := ARRAY[]::text[]; v_x bigint; v_rev5 bigint; v_opac int; v_anon int;
  BEGIN
    -- l'exemplaire du rang 37, retiré auparavant (marqueur posé à la main),
    -- réapparaît réétiqueté
    PERFORM set_config('anarbib.h21_marqueur_retrait', 'on', true);
    UPDATE public.exemplares SET retire_at = now() - interval '1 day', retire_trace = '{"essai": true}'::jsonb WHERE id = e37;
    PERFORM set_config('anarbib.h21_marqueur_retrait', '', true);
    INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
    VALUES (v_src, v_lib, 'essai/l7-pmb-retour.iso', 'l7-pmb-retour.iso', 'marc_iso2709', 'ready_for_review') RETURNING id INTO v_run5;
    INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, item_type, title, subtitle, responsibility_statement, authors, publisher, place_of_publication, publication_year, edition_statement, language, isbn, issn, subjects, raw_payload, normalized_payload, match_status, editorial_decision)
    SELECT v_run5, r.row_no, r.external_key, r.item_type, r.title, r.subtitle, r.responsibility_statement, r.authors, r.publisher, r.place_of_publication, r.publication_year, r.edition_statement, r.language, r.isbn, r.issn, r.subjects, r.raw_payload, r.normalized_payload, 'unreviewed', 'pending'
      FROM jsonb_to_recordset(v_pmb)
        AS r(row_no integer, external_key text, item_type text, title text, subtitle text, responsibility_statement text, authors jsonb, publisher text, place_of_publication text, publication_year text, edition_statement text, language text, isbn text, issn text, subjects jsonb, raw_payload jsonb, normalized_payload jsonb);
    UPDATE ingest.partner_catalog_staging_rows SET normalized_payload = jsonb_set(normalized_payload, '{items,0,source_item_code}', '"L7-REETIQUETE-37"')
     WHERE run_id = v_run5 AND row_no = 37;
    -- deux retirés qui ne se lèvent pas : le rang 14, déplacé dans PMB sous la notice du
    -- rang 15 ; le rang 17, d'une autre source (son code est pourtant dans le fichier)
    PERFORM set_config('anarbib.h21_marqueur_retrait', 'on', true);
    UPDATE public.exemplares SET retire_at = now() - interval '1 day' WHERE id IN (e14, e17);
    PERFORM set_config('anarbib.h21_marqueur_retrait', '', true);
    UPDATE ingest.partner_catalog_staging_rows
       SET normalized_payload = jsonb_set(normalized_payload, '{items}', (normalized_payload->'items')
             || (SELECT s.normalized_payload->'items' FROM ingest.partner_catalog_staging_rows s WHERE s.run_id = v_run5 AND s.row_no = 14))
     WHERE run_id = v_run5 AND row_no = 15;
    UPDATE ingest.partner_catalog_staging_rows SET normalized_payload = jsonb_set(normalized_payload, '{items}', '[]'::jsonb)
     WHERE run_id = v_run5 AND row_no = 14;
    PERFORM ingest.fn_match_partner_catalog_run(v_run5);
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_b := public.fn_import_retraits(v_run5, 200, 0);
    v_p := public.fn_import_proposer_retraits(v_run5);
    EXECUTE 'RESET ROLE';
    v_lotL := (v_p->>'batch_id')::bigint;
    SELECT max(id) FILTER (WHERE published_exemplar_id = e3), max(id) FILTER (WHERE published_exemplar_id = e37)
      INTO dL3, dL37 FROM public.exemplar_drafts WHERE import_retrait->>'nature' = 'levee';
    -- révision
    EXECUTE 'SET LOCAL ROLE authenticated';
    BEGIN PERFORM public.publish_exemplar_draft(dL3); v_h := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
    EXECUTE 'RESET ROLE';
    v_hs := v_hs || v_h;
    v_res := public.fn_batch_review_request(v_lotL, NULL);
    v_rev5 := (v_res->>'review_id')::bigint;
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
    PERFORM public.fn_batch_review_verdict(v_rev5, 'approved', NULL);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    -- refus : sorti du fichier entre-temps ; déjà levé
    BEGIN
      UPDATE ingest.partner_catalog_staging_rows SET normalized_payload = jsonb_set(normalized_payload, '{items}', '[]'::jsonb)
       WHERE run_id = v_run5 AND row_no = 3;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(dL3); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    BEGIN
      PERFORM set_config('anarbib.h21_marqueur_retrait', 'on', true);
      UPDATE public.exemplares SET retire_at = NULL, retire_run_id = NULL WHERE id = e3;
      PERFORM set_config('anarbib.h21_marqueur_retrait', '', true);
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(dL3); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    DECLARE v_run6 bigint;
    BEGIN
      INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
      VALUES (v_src, v_lib, 'essai/l7-r6.iso', 'l7-r6.iso', 'marc_iso2709', 'ready_for_review') RETURNING id INTO v_run6;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(dL3); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- publiée
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_x := public.publish_exemplar_draft(dL3);
    EXECUTE 'RESET ROLE';
    REFRESH MATERIALIZED VIEW public.mv_books_catalog_list_v1;
    EXECUTE 'SET LOCAL ROLE anon';
    PERFORM set_config('request.jwt.claims', json_build_object('role', 'anon')::text, true);
    v_opac := (SELECT count(*) FROM api.catalog_list_anon_v1 WHERE book_id = b3);
    v_anon := (SELECT count(*) FROM public.exemplares WHERE id = e3);
    EXECUTE 'RESET ROLE';
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    IF v_b->'counts'->>'retire_reapparu' = '2' AND v_b->>'bloque_levees' IS NULL
       AND (v_b->'counts'->>'disparu')::int = 0 AND (v_b->'counts'->>'retires')::int = 3
       AND v_b->>'bloque_retraits' = 'pas_export_complet'
       AND (SELECT x->>'constat' FROM jsonb_array_elements(v_b->'items') x WHERE (x->>'exemplar_id')::bigint = e3) = 'deja_la'
       AND (SELECT x->>'constat' FROM jsonb_array_elements(v_b->'items') x WHERE (x->>'exemplar_id')::bigint = e37) = 'reetiquete'
       AND (v_p->>'levees')::int = 2 AND (v_p->>'retraits')::int = 0 AND dL3 IS NOT NULL AND dL37 IS NOT NULL
       AND v_hs = ARRAY['error.publish.review_required', 'error.publish.item_levee_gone_from_file',
                        'error.publish.item_retrait_already_lifted', 'error.publish.item_retrait_run_superseded']
       AND v_x = e3
       AND (SELECT e.retire_at IS NULL AND e.retire_run_id IS NULL AND (e.retire_trace->>'leve_draft_id')::bigint = dL3
                   AND (e.retire_trace->>'leve_run_id')::bigint = v_run5 AND (e.retire_trace->>'draft_id')::bigint = dR3
              FROM public.exemplares e WHERE e.id = e3)
       AND (SELECT h.exemplares_total = 1 AND h.available_count = 1 FROM public.book_holdings h WHERE h.id = h3)
       AND v_opac = 1 AND v_anon = 1
       AND (SELECT count(*) FROM public.fn_peb_search_exemplares((SELECT tombo FROM public.exemplares WHERE id = e3), v_lib)) = 1
       AND EXISTS (SELECT 1 FROM public.catalog_audit_log a WHERE a.action = 'import_retrait_leve' AND a.entity_id = e3)
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||coalesce((v_b - 'items')::text, 'NULL')||' / '||coalesce(v_p::text, 'NULL')
         ||' / '||array_to_string(v_hs, ' , ')||' / opac '||coalesce(v_opac, -1)||' anon '||coalesce(v_anon, -1)); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE';
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T19 ─────────────────────────────────────────────────────────────
  v_t := 'T19 structure : declencheur du marqueur (INSERT et UPDATE), cle etrangere indexee ON DELETE SET NULL, politiques, garde avant les portes';
  BEGIN
    IF EXISTS (SELECT 1 FROM pg_trigger t WHERE t.tgrelid = 'public.exemplares'::regclass AND t.tgname = 'exemplares_marqueur_retrait'
                AND (t.tgtype & 4) = 4 AND (t.tgtype & 16) = 16 AND (t.tgtype & 2) = 2)
       AND EXISTS (SELECT 1 FROM pg_constraint c WHERE c.conname = 'exemplares_retire_run_id_fkey' AND c.confdeltype = 'n')
       AND EXISTS (SELECT 1 FROM pg_indexes WHERE indexname = 'exemplares_retire_run_id_idx')
       AND (SELECT count(*) FROM pg_policy p WHERE p.polrelid = 'public.exemplares'::regclass
              AND position('retire_at IS NULL' IN pg_get_expr(p.polqual, p.polrelid)) > 0) = 2
       AND NOT EXISTS (SELECT 1 FROM pg_policy p WHERE p.polrelid = 'public.exemplares'::regclass AND p.polcmd <> 'r')
       AND position('fn_h21_publier_retrait' IN pg_get_functiondef('public.publish_exemplar_draft(bigint)'::regprocedure))
           < position('lote_importado_sem_revisao' IN pg_get_functiondef('public.publish_exemplar_draft(bigint)'::regprocedure))
       -- (revue sceptique du 10/10) le fonds pris FOR UPDATE avant le contrôle « engagé »
       AND position('from public.book_holdings h where h.id = v_e.holding_id for update' IN pg_get_functiondef('ingest.fn_h21_publier_retrait(bigint, boolean)'::regprocedure)) > 0
       AND position('from public.book_holdings h where h.id = v_e.holding_id for update' IN pg_get_functiondef('ingest.fn_h21_publier_retrait(bigint, boolean)'::regprocedure))
           < position('ingest.fn_h21_retrait_engage(v_e.id)' IN pg_get_functiondef('ingest.fn_h21_publier_retrait(bigint, boolean)'::regprocedure))
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : structure'); END IF;
  EXCEPTION WHEN OTHERS THEN v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T20 ─────────────────────────────────────────────────────────────
  v_t := 'T20 mesure : 1 500 lignes x 4 exemplaires, 5 001 disparus : constat (page de 200) et proposition (1 000 brouillons par appel) < 8 s ; le reste ensuite';
  DECLARE v_bm bigint; v_hm bigint; v_srcM bigint; v_runM bigint; v_b jsonb; v_p jsonb; v_p2 jsonb;
  BEGIN
    INSERT INTO public.books (titulo, bib_ref) VALUES ('L7 mesure', 'L7-M-REF') RETURNING id INTO v_bm;
    INSERT INTO public.book_holdings (book_id, library_id, loanable) VALUES (v_bm, v_lib, true) RETURNING id INTO v_hm;
    INSERT INTO ingest.partner_catalog_sources (partner_name, library_id, relation_status, source_kind, import_enabled)
    VALUES ('L7 source mesure', v_lib, 'mapeada', 'own_catalog', true) RETURNING id INTO v_srcM;
    ALTER TABLE public.exemplares DISABLE TRIGGER trg_exemplar_recompute_availability;
    INSERT INTO public.exemplares (bib_ref, tombo, library_id, holding_id, source_item_code, source_item_id, import_source_id, circulation_policy)
    SELECT 'L7-M-REF', 'L7M-' || i, v_lib, v_hm, 'L7M-C-' || i, 'm' || i, v_srcM, 'ambos' FROM generate_series(1, 5001) i;
    ALTER TABLE public.exemplares ENABLE TRIGGER trg_exemplar_recompute_availability;
    PERFORM public.fn_v2_recompute_holdings_availability(p_holding_ids := ARRAY[v_hm]);
    INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status,
                                                    export_complet, retraits_confirmes_par, retraits_confirmes_le)
    VALUES (v_srcM, v_lib, 'essai/l7-m.iso', 'l7-m.iso', 'marc_iso2709', 'ready_for_review', true, v_coord, now()) RETURNING id INTO v_runM;
    INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, title, normalized_payload, match_status, editorial_decision, proposed_book_id)
    SELECT v_runM, r, 'L7M-' || r, 'L7 mesure',
           jsonb_build_object('items', (SELECT jsonb_agg(jsonb_build_object('source_item_code', 'L7MF-' || r || '-' || k, 'source_item_id', 'f' || r || '-' || k))
                                           FROM generate_series(1, 4) k)),
           'known_record', 'pending', v_bm
      FROM generate_series(1, 1500) r;
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_t0 := clock_timestamp();
    v_b := public.fn_import_retraits(v_runM, 200, 0);
    v_ms := extract(epoch FROM clock_timestamp() - v_t0) * 1000;
    v_t0 := clock_timestamp();
    v_p := public.fn_import_proposer_retraits(v_runM);
    v_ms2 := extract(epoch FROM clock_timestamp() - v_t0) * 1000;
    v_p2 := public.fn_import_proposer_retraits(v_runM);
    EXECUTE 'RESET ROLE';
    RAISE NOTICE 'H21L7-MESURE 1500 lignes x 4 exemplaires, 5001 disparus : constat % ms ; proposer % ms (% brouillons, reste %)',
      round(v_ms), round(v_ms2), v_p->'retraits', v_p->'reste';
    IF (v_b->'counts'->>'disparu')::int = 5001 AND jsonb_array_length(v_b->'items') = 200
       AND (v_p->>'retraits')::int = 1000 AND (v_p->>'reste')::int = 4001 AND (v_p2->>'retraits')::int = 1000 AND (v_p2->>'reste')::int = 3001
       AND v_ms < 8000 AND v_ms2 < 8000
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1;
      v_failures := v_failures || (v_t || ' : ' || coalesce((v_b - 'items')::text, 'NULL') || ' ; ' || coalesce(v_p::text, 'NULL')
                                   || ' ; ' || round(v_ms)::text || ' ms / ' || round(v_ms2)::text || ' ms'); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  IF v_failed = 0 THEN
    RAISE EXCEPTION 'H21-LOT7-RETIRES OK : %/% tests passés', v_passed, v_passed;
  ELSE
    RAISE EXCEPTION 'H21-LOT7-RETIRES ECHEC : %/% OK, % échec(s) | %', v_passed, v_passed + v_failed, v_failed, array_to_string(v_failures, ' || ');
  END IF;
END $$;
